# key (substring of the poet's name in the app) -> (bio, [search keys for the classical biography books])
B = {
'الشافعي': ('محمد بن إدريس بن العباس القرشي المطّلبي، أبو عبد الله، أحد الأئمة الأربعة عند أهل السنة، وإليه يُنسب المذهب الشافعي. وُلد بغزة سنة ١٥٠هـ ونشأ بمكة، وأخذ عن مالك بالمدينة، ثم رحل إلى العراق ومصر، وبها تُوفي سنة ٢٠٤هـ. كان فصيحاً عالماً باللغة وأيام العرب، وله شعر كثير في الحكمة والزهد وعزّة النفس، وفي المنسوب إليه ما لا يصحّ عنه.', ['محمد بن إدريس']),
'المتنبي': ('أحمد بن الحسين بن الحسن الجعفي الكوفي، أبو الطيب، من أشهر شعراء العربية. وُلد بالكوفة سنة ٣٠٣هـ، واتصل بسيف الدولة الحمداني في حلب فقال فيه أجود مدائحه، ثم قصد كافوراً بمصر، ثم عضد الدولة بفارس. قُتل قرب بغداد سنة ٣٥٤هـ. امتاز شعره بالحكمة السائرة والفخر وعلوّ الهمة.', ['أحمد بن الحسين', 'المتنبي']),
'البارودي': ('محمود سامي بن حسن حسني البارودي، شاعر مصري وقائد عسكري، يُعدّ رائد إحياء الشعر العربي في العصر الحديث. وُلد سنة ١٢٥٥هـ، وشارك في الثورة العرابية فنُفي إلى سرنديب سبعة عشر عاماً، ثم عاد إلى مصر وتُوفي بها سنة ١٣٢٢هـ. جارى في شعره فحول الشعراء القدماء في الجزالة والأسلوب.', []),
'علي بن أبي طالب': ('علي بن أبي طالب بن عبد المطلب الهاشمي القرشي، أبو الحسن، ابن عمّ النبي صلى الله عليه وسلم وزوج ابنته فاطمة، ورابع الخلفاء الراشدين، وأحد العشرة المبشّرين بالجنة. استُشهد بالكوفة سنة ٤٠هـ. اشتهر بالشجاعة والعلم والبلاغة، ونُسب إليه شعر كثير في الحكمة والزهد، وأكثره لا يثبت عنه.', ['علي بن أبي طالب']),
'بهاء الدين زهير': ('زهير بن محمد بن علي المهلّبي العتكي، بهاء الدين، شاعر وكاتب من العصر الأيوبي. وُلد بمكة سنة ٥٨١هـ ونشأ بقوص في صعيد مصر، واتصل بالملك الصالح نجم الدين أيوب فكان كاتبه. تُوفي بالقاهرة سنة ٦٥٦هـ. عُرف شعره بالسهولة والرقّة وقرب المأخذ.', ['زهير بن محمد', 'البهاء زهير']),
'أبو العتاهية': ('إسماعيل بن القاسم بن سويد العنزي بالولاء، أبو إسحاق، شاعر عباسي مكثر. وُلد قرب الكوفة سنة ١٣٠هـ ونشأ بها، ثم سكن بغداد واتصل بالخلفاء المهدي والهادي والرشيد. ترك الغزل وانصرف إلى شعر الزهد والموعظة وذكر الموت حتى صار إمام هذا الباب. تُوفي ببغداد سنة ٢١١هـ.', ['أبو العتاهية', 'إسماعيل بن القاسم']),
'أبو فراس': ('الحارث بن سعيد بن حمدان التغلبي، أبو فراس، أمير وشاعر وفارس، ابن عمّ سيف الدولة الحمداني. وُلد سنة ٣٢٠هـ، وولي منبج، وأسره الروم فقال في الأسر قصائده المعروفة بالروميات. قُتل سنة ٣٥٧هـ. يغلب على شعره الفخر والحنين وعزّة النفس.', ['أبو فراس', 'الحارث بن سعيد']),
'المعري': ('أحمد بن عبد الله بن سليمان التنوخي المعرّي، أبو العلاء، شاعر ولغوي من معرّة النعمان بالشام. وُلد سنة ٣٦٣هـ، وكُفّ بصره صغيراً من الجدري، ولزم بيته أكثر عمره وسمّى نفسه «رهين المحبسين». تُوفي سنة ٤٤٩هـ. من دواوينه «سقط الزند» و«اللزوميات»، وفي شعره وعقيدته كلام لأهل العلم.', ['أبو العلاء', 'أحمد بن عبد الله بن سليمان']),
'الشريف الرضي': ('محمد بن الحسين بن موسى الموسوي، أبو الحسن، شاعر بغدادي من العصر العباسي، ولي نقابة الطالبيين ببغداد. وُلد سنة ٣٥٩هـ وتُوفي سنة ٤٠٦هـ. عُرف شعره بالجزالة والفخر، وله «الحجازيات» في الحنين والنسيب.', ['الشريف الرضي', 'محمد بن الحسين بن موسى']),
'أبو نواس': ('الحسن بن هانئ الحكمي بالولاء، أبو علي، شاعر عباسي. وُلد بالأهواز نحو سنة ١٤٠هـ ونشأ بالبصرة، ثم قدم بغداد واتصل بالرشيد والأمين. اشتهر بشعر اللهو والخمر، وله في آخر عمره أبيات في الزهد والتوبة والرجاء. تُوفي ببغداد نحو سنة ١٩٨هـ.', ['أبو نواس', 'الحسن بن هانئ']),
'عنترة': ('عنترة بن شدّاد بن عمرو العبسي، من فرسان العرب وشعرائها في الجاهلية، وأحد أصحاب المعلّقات. كانت أمّه أمَةً حبشية، فلم يُلحقه أبوه بنسبه حتى ظهرت شجاعته في حروب عبس. اشتهر بالفروسية والعفّة والفخر، وبحبّه ابنة عمّه عبلة. مات قبل الإسلام.', ['عنترة']),
'بشار بن برد': ('بشّار بن برد العقيلي بالولاء، أبو معاذ، شاعر مخضرم أدرك الدولتين الأموية والعباسية، ويُعدّ رأس الشعراء المحدَثين. وُلد أعمى بالبصرة ونشأ بها. اتُّهم بالزندقة فقُتل ضرباً في خلافة المهدي نحو سنة ١٦٧هـ.', ['بشار بن برد']),
'أحمد شوقي': ('أحمد بن علي بن أحمد شوقي، شاعر مصري لُقّب بأمير الشعراء. وُلد بالقاهرة سنة ١٢٨٥هـ، ودرس الحقوق بفرنسا، ونُفي إلى الأندلس سنوات ثم عاد. بايعه شعراء العرب بإمارة الشعر سنة ١٣٤٦هـ. تُوفي سنة ١٣٥١هـ. له ديوان «الشوقيات» ومسرحيات شعرية.', []),
'محمد بن حازم': ('محمد بن حازم بن عمرو الباهلي، أبو جعفر، شاعر عباسي من أهل البصرة سكن بغداد. أكثر شعره في القناعة والحكمة وذمّ الحرص، وكان قليل المدح للملوك. تُوفي نحو سنة ٢١٥هـ.', ['محمد بن حازم']),
'البستي': ('علي بن محمد بن الحسين البُستي، أبو الفتح، شاعر وكاتب من بُست في بلاد سجستان. كتب لأمراء الدولة الغزنوية، وعُرف بالحكمة والتجنيس في شعره. أشهر قصائده نونيته «عنوان الحكم». تُوفي سنة ٤٠٠هـ.', ['البستي', 'أبو الفتح']),
'ابن الرومي': ('علي بن العباس بن جُريج، أبو الحسن، شاعر عباسي رومي الأصل. وُلد ببغداد سنة ٢٢١هـ ونشأ بها. عُرف بطول النَّفَس في القصيدة واستقصاء المعاني والوصف والهجاء. تُوفي ببغداد سنة ٢٨٣هـ، وقيل مات مسموماً.', ['ابن الرومي', 'علي بن العباس']),
'لبيد': ('لبيد بن ربيعة بن مالك العامري، أبو عقيل، من شعراء الجاهلية وفرسانها وأحد أصحاب المعلّقات. أدرك الإسلام فوفد على النبي صلى الله عليه وسلم وأسلم وحسن إسلامه، وسكن الكوفة وعُمّر طويلاً، وتُوفي بها نحو سنة ٤١هـ. يغلب على شعره الحكمة وذكر الموت.', ['لبيد بن ربيعة']),
'أبو تمام': ('حبيب بن أوس بن الحارث الطائي، أبو تمّام، شاعر عباسي. وُلد بقرية جاسم من حوران بالشام نحو سنة ١٨٨هـ، ورحل إلى مصر ثم العراق، ومدح المعتصم وغيره. ولي بريد الموصل وتُوفي بها سنة ٢٣١هـ. عُرف بالبديع وغوص المعاني، وهو صاحب «ديوان الحماسة».', ['أبو تمام', 'حبيب بن أوس']),
'العباس بن الأحنف': ('العباس بن الأحنف بن الأسود الحنفي اليمامي، أبو الفضل، شاعر عباسي نشأ ببغداد. قصر شعره على الغزل العفيف، ولم يمدح ولم يهجُ. كان من ندماء الرشيد. تُوفي نحو سنة ١٩٢هـ.', ['العباس بن الأحنف']),
'ابن قيم': ('محمد بن أبي بكر بن أيوب الزُّرَعي الدمشقي، شمس الدين، المعروف بابن قيّم الجوزية، من كبار علماء أهل السنة. وُلد بدمشق سنة ٦٩١هـ، ولازم شيخ الإسلام ابن تيمية وحُبس معه في قلعة دمشق. له مؤلفات كثيرة مشهورة، وله في النظم «الكافية الشافية» المعروفة بالنونية، والقصيدة الميمية. تُوفي بدمشق سنة ٧٥١هـ.', []),
'عبد الله بن المبارك': ('عبد الله بن المبارك بن واضح الحنظلي بالولاء المروزي، أبو عبد الرحمن، الإمام الحافظ المجاهد. وُلد بمرو سنة ١١٨هـ، وجمع الحديث والفقه والزهد والجهاد والتجارة. له كتاب «الزهد» وكتاب «الجهاد»، وله شعر في الزهد والحكمة. تُوفي بهِيت منصرفاً من الغزو سنة ١٨١هـ.', ['عبد الله بن المبارك', 'ابن المبارك']),
'ابن المعتز': ('عبد الله بن محمد المعتز بالله ابن المتوكل العباسي، أبو العباس، أمير وشاعر وأديب. وُلد ببغداد سنة ٢٤٧هـ. بويع بالخلافة يوماً وليلة ثم خُلع وقُتل سنة ٢٩٦هـ. اشتهر بالتشبيه والوصف، وهو صاحب كتاب «البديع» و«طبقات الشعراء».', ['ابن المعتز', 'عبد الله بن المعتز']),
'البرعي': ('عبد الرحيم بن أحمد البُرَعي اليماني، شاعر من أهل اليمن عاش في القرن الثامن الهجري، وتُوفي سنة ٨٠٣هـ. له ديوان أكثره في المدائح والابتهالات، وفي بعض شعره غلوّ نبّه عليه أهل العلم.', []),
'البحتري': ('الوليد بن عُبيد بن يحيى الطائي، أبو عُبادة، شاعر عباسي. وُلد بمنبج سنة ٢٠٦هـ، وتتلمذ لأبي تمام، ثم قصد العراق فمدح المتوكل ومن بعده من الخلفاء. عُرف بحسن الديباجة وعذوبة اللفظ والوصف. عاد إلى منبج وتُوفي بها سنة ٢٨٤هـ.', ['البحتري', 'الوليد بن عبيد']),
'أبو الأسود': ('ظالم بن عمرو بن سفيان الدؤلي الكناني، أبو الأسود، من سادات التابعين. صحب عليّ بن أبي طالب رضي الله عنه وولي له البصرة، وهو أوّل من وضع علم النحو ونقط المصحف. له شعر في الحكمة. تُوفي بالبصرة سنة ٦٩هـ.', ['أبو الأسود الدؤلي', 'أبو الأسود']),
'عمر بن أبي ربيعة': ('عمر بن عبد الله بن أبي ربيعة المخزومي القرشي، أبو الخطّاب، شاعر قريش في العصر الأموي. وُلد بالمدينة سنة ٢٣هـ ونشأ بمكة. قصر أكثر شعره على الغزل. تُوفي نحو سنة ٩٣هـ.', ['عمر بن أبي ربيعة']),
'زهير بن أبي سلمى': ('زهير بن أبي سُلمى ربيعة بن رياح المزني، من شعراء الجاهلية الثلاثة المقدَّمين، وأحد أصحاب المعلّقات. عاش في غطفان، ومدح هَرِم بن سنان والحارث بن عوف لسعيهما في الصلح بين عبس وذبيان. عُرف بالحكمة وتنقيح شعره. مات قبيل البعثة.', ['زهير بن أبي سلمى']),
'الأعشى': ('ميمون بن قيس بن جندل، من بني قيس بن ثعلبة من بكر بن وائل، أبو بصير، من شعراء الجاهلية الفحول وأحد أصحاب المعلّقات. كان كثير الوفود على الملوك، ولُقّب «صنّاجة العرب». أدرك الإسلام ولم يُسلم، ومات باليمامة نحو سنة ٧هـ.', ['الأعشى']),
'مجنون ليلى': ('قيس بن الملوَّح بن مزاحم العامري، من شعراء الغزل العذري في العصر الأموي. اشتهر بحبّه ليلى العامرية وهيامه بها حتى لُقّب بالمجنون. تُوفي نحو سنة ٦٨هـ. وفي أخباره وما يُنسب إليه من الشعر اختلاف كثير بين الرواة.', ['قيس بن الملوح', 'مجنون']),
'حسان بن ثابت': ('حسّان بن ثابت بن المنذر بن حرام الخزرجي الأنصاري، أبو الوليد، شاعر مخضرم وصحابي جليل. اشتهر في الجاهلية بمدح ملوك الغساسنة، ولمّا أسلم صار شاعر النبي صلى الله عليه وسلم ينافح عنه ويهجو من ناوأه. عُمّر طويلاً، وتُوفي بالمدينة نحو سنة ٥٤هـ.', ['حسان بن ثابت']),
'القحطاني': ('أبو محمد عبد الله بن محمد الأندلسي القحطاني، صاحب النونية المشهورة في عقيدة أهل السنة والآداب والمواعظ. من علماء الأندلس، وأخباره في كتب التراجم قليلة.', []),
'ابن زمرك': ('محمد بن يوسف بن محمد الصُّرَيحي، أبو عبد الله، المعروف بابن زَمرَك، وزير وشاعر أندلسي من غرناطة. وُلد سنة ٧٣٣هـ، وتتلمذ للسان الدين ابن الخطيب، وكتب لملوك بني الأحمر، ونُقش شعره على جدران قصر الحمراء. قُتل نحو سنة ٧٩٥هـ.', []),
'الطغرائي': ('الحسين بن علي بن محمد الأصبهاني، أبو إسماعيل، مؤيّد الدين، المعروف بالطُّغرائي، وزير وكاتب وشاعر. وُلد بأصبهان سنة ٤٥٥هـ، ووزر للسلطان مسعود السلجوقي. قُتل سنة ٥١٣هـ. أشهر شعره «لامية العجم».', ['الطغرائي']),
'كعب بن زهير': ('كعب بن زهير بن أبي سُلمى المزني، شاعر مخضرم وصحابي، ابن الشاعر زهير. أهدر النبي صلى الله عليه وسلم دمه لشعرٍ قاله، ثم جاءه مسلماً تائباً وأنشده لاميته «بانت سعاد» فعفا عنه. تُوفي نحو سنة ٢٦هـ.', ['كعب بن زهير']),
'القاضي عبد الوهاب': ('عبد الوهاب بن علي بن نصر التغلبي البغدادي، أبو محمد، القاضي، من أعلام فقهاء المالكية. وُلد ببغداد سنة ٣٦٢هـ، وولي القضاء، ثم خرج منها لضيق الحال إلى مصر فتُوفي بها سنة ٤٢٢هـ. له «التلقين» و«المعونة»، وله شعر حسن.', ['عبد الوهاب بن علي']),
'صفي الدين الحلي': ('عبد العزيز بن سرايا بن علي الطائي السِّنبِسي، صفيّ الدين الحِلّي، شاعر من العصر المملوكي. وُلد بالحِلّة في العراق سنة ٦٧٧هـ، ورحل إلى ماردين ومصر ومدح ملوكها. تُوفي ببغداد نحو سنة ٧٥٠هـ. له ديوان كبير، وهو من أوائل من نظم البديعيات.', ['صفي الدين', 'عبد العزيز بن سرايا']),
'الفرزدق': ('همّام بن غالب بن صعصعة التميمي الدارمي، أبو فراس، من فحول شعراء العصر الأموي. وُلد بالبصرة ونشأ بها، واشتهر بالفخر وبالنقائض بينه وبين جرير. قال أهل اللغة: لولا شعره لذهب ثلث لغة العرب. تُوفي بالبصرة سنة ١١٠هـ.', ['الفرزدق']),
'الأبيوردي': ('محمد بن أحمد بن محمد القرشي الأموي، أبو المظفّر الأبيوردي، شاعر ونسّابة ولغوي من أهل خراسان. قدم بغداد وخدم في ديوانها. تُوفي بأصبهان سنة ٥٠٧هـ. قسم ديوانه إلى العراقيات والنجديات والوجديات.', ['الأبيوردي']),
'الرصافي': ('معروف بن عبد الغني الرصافي، شاعر عراقي من العصر الحديث. وُلد ببغداد سنة ١٢٩٤هـ، وتتلمذ لمحمود شكري الآلوسي، واشتغل بالتعليم والصحافة والنيابة. تُوفي ببغداد سنة ١٣٦٤هـ. يغلب على شعره الموضوعات الاجتماعية والوطنية.', []),
'الرندي': ('صالح بن يزيد بن صالح النَّفزي الرُّندي، أبو البقاء، أديب وشاعر وفقيه أندلسي من أهل رُندة. وُلد سنة ٦٠١هـ وتُوفي سنة ٦٨٤هـ. اشتهر بنونيته في رثاء مدن الأندلس التي أوّلها «لكل شيء إذا ما تمّ نقصان».', []),
'الخنساء': ('تُماضر بنت عمرو بن الحارث السُّلَمية، المعروفة بالخنساء، أشهر شواعر العرب. عاشت أكثر عمرها في الجاهلية، ثم أدركت الإسلام فوفدت مع قومها على النبي صلى الله عليه وسلم وأسلمت. اشتهرت برثاء أخويها صخر ومعاوية، وأجمع أهل العلم بالشعر على أنه لم تكن امرأة أشعر منها. تُوفيت نحو سنة ٢٤هـ.', ['الخنساء']),
'النابغة الشيباني': ('عبد الله بن المخارق بن سُليم الشيباني، شاعر من العصر الأموي من بادية الشام. وفد على الخلفاء بدمشق ومدح عبد الملك بن مروان وأبناءه. تُوفي نحو سنة ١٢٥هـ.', ['النابغة الشيباني']),
'ربيعة الرقي': ('ربيعة بن ثابت بن لجأ الأسدي الرَّقّي، أبو ثابت، شاعر عباسي من أهل الرَّقّة. كان ضريراً، ومدح المهدي والرشيد. عُرف بالغزل الرقيق. تُوفي نحو سنة ١٩٨هـ.', ['ربيعة الرقي']),
'ابن الدّمَينة': ('عبد الله بن عُبيد الله بن أحمد الخثعمي، أبو السَّريّ، المعروف بابن الدُّمَينة نسبةً إلى أمّه، شاعر من العصر الأموي. اشتهر بالغزل الرقيق. قُتل غيلةً نحو سنة ١٣٠هـ.', ['ابن الدمينة']),
'البوصيري': ('محمد بن سعيد بن حمّاد الصنهاجي البوصيري، شرف الدين، شاعر مصري من العصر المملوكي. وُلد سنة ٦٠٨هـ وتُوفي بالإسكندرية نحو سنة ٦٩٦هـ. اشتهر بقصيدته «البردة» في المديح، وفيها أبيات انتقدها أهل العلم لما فيها من الغلوّ.', ['البوصيري']),
'الإلبيري': ('إبراهيم بن مسعود بن سعد التُّجيبي، أبو إسحاق الإلبيري، فقيه وزاهد وشاعر أندلسي من أهل إلبيرة. يغلب على شعره الزهد والموعظة والحثّ على العلم، وأشهره تائيته «تفتّ فؤادك الأيام فتّا». تُوفي نحو سنة ٤٦٠هـ.', []),
'مسعر بن كدام': ('مِسعَر بن كِدام بن ظُهير الهلالي الكوفي، أبو سلمة، الإمام الحافظ، من ثقات المحدّثين وعبّادهم. روى عنه سفيان الثوري وابن عيينة وغيرهما، وكان يُسمّى «المصحف» لإتقانه. تُوفي سنة ١٥٥هـ.', ['مسعر بن كدام']),
'ذو الإصبع': ('حُرثان بن الحارث بن محرِّث العَدواني، المعروف بذي الإصبع، شاعر جاهلي وحكيم من حكماء العرب وفرسانها. عُمّر طويلاً، وله وصايا وشعر في الحكمة والفخر. مات قبل الإسلام.', ['ذو الإصبع']),
'ابن خفاجة': ('إبراهيم بن أبي الفتح بن عبد الله بن خفاجة الهواري، أبو إسحاق، شاعر أندلسي من جزيرة شُقْر شرقي الأندلس. وُلد سنة ٤٥٠هـ وتُوفي سنة ٥٣٣هـ. غلب على شعره وصف الطبيعة حتى لُقّب بالجنّان.', ['ابن خفاجة']),
'منصور الفقيه': ('منصور بن إسماعيل بن عمر التميمي، أبو الحسن، فقيه شافعي وشاعر ضرير، سكن مصر وتُوفي بها سنة ٣٠٦هـ. له مصنّفات في الفقه، وشعر سائر في الحكمة.', ['منصور بن إسماعيل']),
'أبو حيان': ('محمد بن يوسف بن علي بن حيّان الغرناطي الأندلسي، أثير الدين، أبو حيّان، إمام النحو والتفسير في عصره. وُلد بغرناطة سنة ٦٥٤هـ، ورحل إلى المشرق واستقرّ بالقاهرة وتُوفي بها سنة ٧٤٥هـ. صاحب تفسير «البحر المحيط».', []),
'أبو الشمقمق': ('مروان بن محمد، أبو محمد، المعروف بأبي الشَّمَقمَق، شاعر عباسي من أهل البصرة قدم بغداد. عُرف بالهجاء وشكوى الفقر. تُوفي نحو سنة ٢٠٠هـ.', ['أبو الشمقمق']),
'النابغة الذبياني': ('زياد بن معاوية بن ضِباب الذبياني الغطفاني، أبو أمامة، من شعراء الجاهلية الثلاثة المقدَّمين وأحد أصحاب المعلّقات. كانت تُضرب له قبّة بسوق عكاظ فيحكم بين الشعراء. اتصل بالنعمان بن المنذر وبملوك غسان، واشتهر باعتذارياته. مات قبيل البعثة.', ['النابغة الذبياني']),
'صالح بن عبد القدوس': ('صالح بن عبد القدّوس بن عبد الله الأزدي بالولاء، أبو الفضل، شاعر حكيم من أهل البصرة. شعره كلّه أمثال وحِكم وآداب. اتُّهم بالزندقة فقتله المهدي ببغداد نحو سنة ١٦٧هـ.', ['صالح بن عبد القدوس']),
'طرفة': ('طَرَفة بن العبد بن سفيان البكري الوائلي، شاعر جاهلي من الطبقة الأولى وأحد أصحاب المعلّقات. وُلد في البحرين، واتصل بالملك عمرو بن هند، ثم قُتل شابّاً بأمره وهو ابن ستّ وعشرين سنة فيما يُروى.', ['طرفة']),
'محمود الوراق': ('محمود بن حسن الورّاق، أبو الحسن، شاعر عباسي من أهل بغداد. أكثر شعره في المواعظ والحِكم والزهد، وروى عنه ابن أبي الدنيا. تُوفي نحو سنة ٢٢٥هـ.', ['محمود الوراق']),
'إبراهيم بن المهدي': ('إبراهيم بن محمد المهدي بن المنصور العباسي، أبو إسحاق، أمير من بني العباس وأخو هارون الرشيد. بويع بالخلافة ببغداد أيام المأمون ثم استتر، فظفر به المأمون وعفا عنه. كان شاعراً فصيحاً. تُوفي بسامرّاء سنة ٢٢٤هـ.', ['إبراهيم بن المهدي']),
'الحسين بن مطير': ('الحسين بن مُطَير بن مكمّل الأسدي بالولاء، شاعر مخضرم أدرك الدولتين الأموية والعباسية. مدح معن بن زائدة والمهدي. تُوفي نحو سنة ١٦٩هـ.', ['الحسين بن مطير']),
'كُثَيِّر': ('كُثَيِّر بن عبد الرحمن بن الأسود الخزاعي، أبو صخر، شاعر من أهل الحجاز في العصر الأموي. اشتهر بحبّه عزّة بنت جميل الضمرية فنُسب إليها. وفد على عبد الملك بن مروان. تُوفي بالمدينة سنة ١٠٥هـ.', ['كثير عزة', 'كثير بن عبد الرحمن']),
'المبرد': ('محمد بن يزيد بن عبد الأكبر الثُّمالي الأزدي، أبو العباس، المعروف بالمبرِّد، إمام العربية ببغداد في زمانه. وُلد بالبصرة سنة ٢١٠هـ وتُوفي ببغداد سنة ٢٨٦هـ. صاحب «الكامل» و«المقتضب».', ['المبرد', 'محمد بن يزيد']),
'ابن الوردي': ('عمر بن مظفّر بن عمر المعرّي الكندي، زين الدين، المعروف بابن الوردي، فقيه شافعي وأديب وشاعر ومؤرخ. وُلد بمعرّة النعمان سنة ٦٩١هـ، وولي القضاء بمنبج، وتُوفي بحلب بالطاعون سنة ٧٤٩هـ. أشهر شعره لاميته في النصائح والآداب.', ['ابن الوردي', 'عمر بن مظفر']),
'الشيرازي': ('إبراهيم بن علي بن يوسف الفيروزآبادي الشيرازي، أبو إسحاق، إمام الشافعية في عصره. وُلد سنة ٣٩٣هـ، ودرّس بالمدرسة النظامية ببغداد، واشتهر بالزهد والورع وقوة المناظرة. له «المهذّب» و«التنبيه» و«اللمع». تُوفي ببغداد سنة ٤٧٦هـ.', ['أبو إسحاق الشيرازي', 'إبراهيم بن علي']),
'سلامة بن جندل': ('سلامة بن جندل بن عبد عمرو السعدي التميمي، شاعر جاهلي وفارس من فرسان تميم. اشتهر بوصف الخيل. مات قبل الإسلام.', ['سلامة بن جندل']),
'الأفوه': ('صلاءة بن عمرو بن مالك الأودي المذحجي، الملقّب بالأفوه، شاعر جاهلي قديم وسيّد قومه وقائدهم في حروبهم. يُعدّ من حكماء العرب، وشعره في الحكمة سائر.', ['الأفوه']),
'جميل بثينة': ('جميل بن عبد الله بن معمر العُذري القُضاعي، أبو عمرو، إمام شعراء الغزل العذري في العصر الأموي. اشتهر بحبّه بثينة من فتيات قومه. قصد مصر وتُوفي بها سنة ٨٢هـ.', ['جميل بن عبد الله', 'جميل بثينة', 'جميل بن معمر']),
'لسان الدين': ('محمد بن عبد الله بن سعيد السلماني، لسان الدين ابن الخطيب، وزير ومؤرخ وأديب وطبيب أندلسي. وُلد بلوشة سنة ٧١٣هـ، ووزر لبني الأحمر بغرناطة ولُقّب بذي الوزارتين. قُتل بفاس سنة ٧٧٦هـ. له «الإحاطة في أخبار غرناطة».', []),
'ذو الرمة': ('غيلان بن عُقبة بن نُهيس العدوي، أبو الحارث، المعروف بذي الرُّمّة، من فحول شعراء العصر الأموي. كان مقيماً بالبادية، واشتهر بوصف الصحراء وبحبّه ميّة. تُوفي سنة ١١٧هـ.', ['ذو الرمة']),
'الشاب الظريف': ('محمد بن سليمان بن علي التلمساني، شمس الدين، المعروف بالشابّ الظريف، شاعر من العصر المملوكي. وُلد بالقاهرة سنة ٦٦١هـ ونشأ بدمشق، وتُوفي بها شابّاً سنة ٦٨٨هـ. شعره رقيق أكثره في الغزل.', ['الشاب الظريف']),
'ابن حزم': ('علي بن أحمد بن سعيد بن حزم الأندلسي القرطبي، أبو محمد، الإمام الحافظ الفقيه الظاهري. وُلد بقرطبة سنة ٣٨٤هـ، ونشأ في بيت وزارة ثم انصرف إلى العلم. له «المحلّى» و«الفصل» و«طوق الحمامة»، وله شعر كثير. تُوفي سنة ٤٥٦هـ.', ['ابن حزم', 'علي بن أحمد بن سعيد']),
'العقاد': ('عباس بن محمود بن إبراهيم العقّاد، أديب وشاعر وناقد مصري. وُلد بأسوان سنة ١٣٠٦هـ، وتعلّم بنفسه، وألّف نحو مئة كتاب. أسّس مع المازني وشكري مدرسة «الديوان» في الشعر. تُوفي بالقاهرة سنة ١٣٨٣هـ.', []),
'إبراهيم بن العباس الصولي': ('إبراهيم بن العباس بن محمد بن صُول، أبو إسحاق، كاتب وشاعر عباسي من كبار كتّاب الدواوين. ولي ديوان الضياع والنفقات بسامرّاء. شعره مقطوعات قصيرة جيّدة. تُوفي سنة ٢٤٣هـ.', ['إبراهيم بن العباس']),
'عروة بن الورد': ('عروة بن الورد بن زيد العبسي، شاعر جاهلي وفارس من أجواد العرب. لُقّب «عروة الصعاليك» لأنه كان يجمع الفقراء ويقوم بأمرهم ويقاسمهم ما يغنم. مات قبل الإسلام.', ['عروة بن الورد']),
'الخليل': ('الخليل بن أحمد بن عمرو بن تميم الفراهيدي الأزدي، أبو عبد الرحمن، إمام اللغة والنحو، وواضع علم العَروض. وُلد بالبصرة سنة ١٠٠هـ، وهو أستاذ سيبويه، وصاحب معجم «العين». كان زاهداً متقلّلاً من الدنيا. تُوفي بالبصرة نحو سنة ١٧٠هـ.', ['الخليل بن أحمد']),
'كعب بن سعد الغنوي': ('كعب بن سعد بن عمرو الغَنَوي، شاعر جاهلي، وقيل أدرك الإسلام. أشهر شعره بائيته في رثاء أخيه أبي المِغوار، وهي من عيون المراثي.', ['كعب بن سعد']),
'ابن حيّوس': ('محمد بن سلطان بن محمد بن حيّوس الغَنَوي، أبو الفتيان، شاعر الشام في عصره. وُلد بدمشق سنة ٣٩٤هـ، ومدح بني مرداس أصحاب حلب. تُوفي بحلب سنة ٤٧٣هـ.', ['ابن حيوس']),
'العباس بن مرداس': ('العباس بن مرداس بن أبي عامر السُّلَمي، أبو الهيثم، شاعر مخضرم وفارس وسيّد في قومه، وأمّه الخنساء الشاعرة فيما يُروى. أسلم قبيل فتح مكة وشهد الفتح وحُنيناً. تُوفي في خلافة عمر نحو سنة ١٨هـ.', ['العباس بن مرداس']),
'سبط ابن التعاويذي': ('محمد بن عبيد الله بن عبد الله، أبو الفتح، المعروف بسبط ابن التعاويذي، شاعر العراق في عصره. وُلد ببغداد سنة ٥١٩هـ، وكتب في ديوان المقاطعات، وكُفّ بصره في آخر عمره. تُوفي سنة ٥٨٣هـ.', ['ابن التعاويذي']),
'التهامي': ('علي بن محمد بن فهد التهامي، أبو الحسن، شاعر من أهل تهامة قدم الشام والعراق. حُبس بالقاهرة وقُتل في سجنه سنة ٤١٦هـ. أشهر شعره رائيته في رثاء ولده، وأوّلها «حكم المنيّة في البريّة جاري».', ['التهامي']),
'خُبيب': ('خُبيب بن عديّ بن مالك الأوسي الأنصاري، صحابي شهد بدراً. أُسر يوم الرَّجيع وبيع بمكة، فصلبته قريش بالتنعيم سنة ٤هـ، وهو أوّل من سنّ الركعتين عند القتل. وأبياته التي قالها قبل قتله مشهورة.', ['خبيب بن عدي']),
'امرؤ القيس': ('امرؤ القيس بن حُجر بن الحارث الكندي، أشهر شعراء الجاهلية وصاحب أولى المعلّقات. كان أبوه ملكاً على بني أسد فقتلوه، فقضى حياته يطلب ثأره ومُلكه، حتى قصد قيصر الروم يستنصره، ومات في طريق عودته بأنقرة نحو سنة ٨٠ قبل الهجرة.', ['امرؤ القيس', 'امرئ القيس']),
'جبران': ('جبران خليل جبران، أديب وشاعر ورسّام لبناني من أدباء المهجر. وُلد في بشرّي بلبنان سنة ١٨٨٣م، وهاجر إلى الولايات المتحدة، وأسّس مع رفاقه «الرابطة القلمية» بنيويورك، وتُوفي بها سنة ١٩٣١م. كتب بالعربية والإنجليزية.', []),
'أبو الطفيل': ('عامر بن واثلة بن عبد الله الكناني الليثي، أبو الطُّفيل، وُلد عام أُحد وأدرك من حياة النبي صلى الله عليه وسلم ثماني سنين. وهو آخر من مات من الصحابة، تُوفي بمكة نحو سنة ١١٠هـ. كان فاضلاً عاقلاً شاعراً.', ['أبو الطفيل', 'عامر بن واثلة']),
'كشاجم': ('محمود بن الحسين بن السندي، أبو الفتح، المعروف بكُشاجِم، شاعر وأديب من أهل الرملة بفلسطين. اتصل بسيف الدولة الحمداني. عُرف بالوصف. تُوفي نحو سنة ٣٦٠هـ.', ['كشاجم']),
'مسلم بن الوليد': ('مسلم بن الوليد الأنصاري بالولاء، أبو الوليد، المعروف بصريع الغواني، شاعر عباسي من أهل الكوفة. مدح الرشيد والبرامكة، وهو من أوائل من أكثر من البديع في شعره. تُوفي بجرجان سنة ٢٠٨هـ.', ['مسلم بن الوليد']),
'عبد الله بن رواحة': ('عبد الله بن رواحة بن ثعلبة الخزرجي الأنصاري، أبو محمد، صحابي جليل، أحد النقباء ليلة العقبة، شهد بدراً وما بعدها. كان أحد شعراء النبي صلى الله عليه وسلم الثلاثة مع حسّان وكعب بن مالك. استُشهد أميراً في غزوة مؤتة سنة ٨هـ.', ['عبد الله بن رواحة']),
'ابن تيمية': ('أحمد بن عبد الحليم بن عبد السلام بن تيمية الحرّاني ثم الدمشقي، تقيّ الدين، أبو العباس، شيخ الإسلام. وُلد بحرّان سنة ٦٦١هـ ونشأ بدمشق، وبرع في علوم الشريعة، وجاهد بلسانه وقلمه وسيفه، وامتُحن وسُجن مراراً. تُوفي محبوساً بقلعة دمشق سنة ٧٢٨هـ. نظمه قليل، ومنه تائيته في القدر.', []),
'ابن الجوزي': ('عبد الرحمن بن علي بن محمد القرشي التيمي البغدادي، جمال الدين، أبو الفرج ابن الجوزي، الإمام الحافظ الواعظ. وُلد ببغداد نحو سنة ٥١٠هـ، وكان إمام الوعظ في زمانه، وصنّف مئات الكتب، منها «زاد المسير» و«صيد الخاطر» و«المنتظم». تُوفي ببغداد سنة ٥٩٧هـ.', ['ابن الجوزي']),
'معن بن أوس': ('مَعن بن أوس بن نصر المُزَني، شاعر مخضرم أدرك الجاهلية والإسلام وأسلم. له مدائح في بعض الصحابة، وعُمّر إلى أيام ابن الزبير. تُوفي بالمدينة نحو سنة ٦٤هـ. أشهر شعره لاميته في الحلم وصلة الرحم.', ['معن بن أوس']),
'أمية بن عبد العزيز': ('أميّة بن عبد العزيز بن أبي الصلت الداني الأندلسي، أبو الصلت، حكيم وطبيب وأديب وشاعر. وُلد بدانية سنة ٤٦٠هـ، ورحل إلى مصر ثم استقرّ بالمهدية في إفريقية وتُوفي بها سنة ٥٢٩هـ.', ['أمية بن عبد العزيز']),
'عبد الصمد بن المعذّل': ('عبد الصمد بن المعذَّل بن غيلان العبدي، أبو القاسم، شاعر عباسي من أهل البصرة. عُرف بالهجاء. تُوفي نحو سنة ٢٤٠هـ.', ['عبد الصمد بن المعذل']),
'عبيد الله بن عبد الله بن طاهر': ('عبيد الله بن عبد الله بن طاهر بن الحسين الخزاعي، أبو أحمد، أمير من بيت آل طاهر، ولي شرطة بغداد. كان أديباً شاعراً مترسّلاً. تُوفي ببغداد سنة ٣٠٠هـ.', ['عبيد الله بن عبد الله بن طاهر']),
# new poets
'السموأل': ('السموأل بن غَريض بن عادياء، شاعر جاهلي من أهل تيماء، صاحب الحصن المعروف بالأبلق. يُضرب به المثل في الوفاء، لقصّته في حفظ دروع امرئ القيس التي أودعها عنده. أشهر شعره لاميته في الفخر ومكارم الأخلاق، ويرويها بعض العلماء لغيره.', ['السموأل']),
'حاتم الطائي': ('حاتم بن عبد الله بن سعد الطائي، أبو عَديّ، شاعر جاهلي وفارس، يُضرب به المثل في الجود. أخباره في الكرم كثيرة مشهورة، وأكثر شعره في السخاء ومكارم الأخلاق. مات قبل البعثة، وأدرك ابنه عَديّ الإسلام فأسلم.', ['حاتم الطائي', 'حاتم بن عبد الله']),
'الشنفرى': ('الشَّنفَرى الأزدي، شاعر جاهلي من الصعاليك العدّائين، يُضرب به المثل في سرعة العدو. اختلف الرواة في اسمه. تُنسب إليه «لامية العرب» في الأنفة والصبر على شظف العيش، وهي من أشهر قصائد العرب.', ['الشنفرى']),
'الحطيئة': ('جَرول بن أوس بن مالك العبسي، أبو مُليكة، المعروف بالحطيئة، شاعر مخضرم أدرك الجاهلية والإسلام. كان متين الشعر، كثير الهجاء حتى هجا نفسه، وحبسه عمر بن الخطاب رضي الله عنه لهجائه الزبرقان بن بدر. تُوفي نحو سنة ٤٥هـ.', ['الحطيئة']),
'أبو ذؤيب': ('خُوَيلد بن خالد بن محرِّث الهُذَلي، أبو ذؤيب، شاعر مخضرم، وهو أشعر هُذيل. أسلم وخرج في الفتوح، وتُوفي في خلافة عثمان رضي الله عنه نحو سنة ٢٧هـ. أشهر شعره عينيته التي رثى بها أبناءه، وكانوا قد هلكوا في عام واحد.', ['أبو ذؤيب']),
'النابغة الجعدي': ('قيس بن عبد الله بن عُدَس الجعدي العامري، أبو ليلى، شاعر مخضرم وصحابي من المعمَّرين. وفد على النبي صلى الله عليه وسلم وأنشده من شعره. شهد صفّين مع عليّ رضي الله عنه، وتُوفي بأصبهان نحو سنة ٥٠هـ.', ['النابغة الجعدي']),
'متمم': ('متمِّم بن نُوَيرة بن جمرة اليربوعي التميمي، أبو نهشل، شاعر مخضرم وصحابي. اشتهر بمراثيه في أخيه مالك، وهي من أجود ما قيل في رثاء الإخوة. تُوفي نحو سنة ٣٠هـ.', ['متمم بن نويرة']),
'جرير': ('جرير بن عطية بن حذيفة الخَطَفى الكلبي اليربوعي التميمي، أبو حَزرة، من فحول شعراء العصر الأموي. وُلد باليمامة، واشتهر بالنقائض بينه وبين الفرزدق والأخطل، وكان أرقّهم نسيباً. تُوفي باليمامة سنة ١١٠هـ.', ['جرير بن عطية', 'جرير']),
'ابن دريد': ('محمد بن الحسن بن دُرَيد الأزدي، أبو بكر، إمام اللغة والأدب في عصره. وُلد بالبصرة سنة ٢٢٣هـ وتُوفي ببغداد سنة ٣٢١هـ. صاحب «جمهرة اللغة» و«الاشتقاق»، وأشهر شعره «المقصورة» المشتملة على الحِكم والآداب.', ['ابن دريد', 'محمد بن الحسن بن دريد']),
'ابن زيدون': ('أحمد بن عبد الله بن أحمد بن زيدون المخزومي القرطبي، أبو الوليد، وزير وكاتب وشاعر أندلسي. وُلد بقرطبة سنة ٣٩٤هـ، ووزر لبني جَهوَر ثم لبني عبّاد بإشبيلية، وتُوفي بها سنة ٤٦٣هـ. أشهر شعره نونيته «أضحى التنائي».', ['ابن زيدون']),
'ابن عبد ربه': ('أحمد بن محمد بن عبد ربّه القرطبي، أبو عمر، أديب الأندلس وشاعرها. وُلد سنة ٢٤٦هـ وتُوفي بقرطبة سنة ٣٢٨هـ. صاحب كتاب «العقد الفريد». وله في آخر عمره قصائد في الزهد والتوبة سمّاها «الممحِّصات».', ['ابن عبد ربه']),
'المعتمد': ('محمد بن عبّاد بن محمد اللخمي، أبو القاسم، المعتمد على الله، صاحب إشبيلية وقرطبة وأكبر ملوك الطوائف بالأندلس. وُلد سنة ٤٣١هـ. خلعه المرابطون سنة ٤٨٤هـ وحملوه أسيراً إلى أغمات بالمغرب، فمات بها سنة ٤٨٨هـ. وشعره في الأسر من أرقّ الشعر.', ['المعتمد بن عباد', 'المعتمد']),
'حافظ إبراهيم': ('محمد حافظ بن إبراهيم فهمي، شاعر مصري لُقّب بشاعر النيل. وُلد سنة ١٢٨٧هـ، وعمل ضابطاً ثم في دار الكتب المصرية. يغلب على شعره الموضوعات الاجتماعية والوطنية والدفاع عن اللغة العربية. تُوفي بالقاهرة سنة ١٣٥١هـ.', []),
}
